raw:
{
  "spells": [
    {
      "id": "spell_faith_07",
      "theory": "施术者将魔力导入刻有简易环纹的灯盏或提灯表面，使纹路在器物周围形成一层极薄的干扰场。这层场不阻挡实体，只让低阶邪秽靠近时感到不安而退开。护灯纹依附在受术的照明器具上，受术者需提灯或近灯而立，灯灭则场散。",
      "casting": "单手托住灯座，另一手食指沿灯罩外壁画一个闭合圆环，同时缓缓注入魔力，直到环纹浮现微光。",
      "failure": "圆环画得不闭合，微光会从缺口处漏散，护灯纹在几分钟内自行熄灭。提灯者会感到一阵无来由的寒意，邪秽可能趁机靠近。",
      "counters": [
        "用湿泥或厚布抹糊灯盏表面的环纹，干扰场便无法成形。",
        "以另一股魔力冲击灯盏，使环纹过载碎裂，护灯纹立刻消失。"
      ],
      "socialConsequences": "守夜人和赶夜路的商贩愿意为提灯求一道护灯纹，尤其在传闻有邪秽出没的路段。灯烛铺的工匠乐见灯盏附加价值提高，但巡夜队会盘问陌生人为何在公共灯柱上私刻纹路。若在他人住宅外墙的灯上施术，须先征得住户同意，否则被视为擅动他人财物。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把环纹画歪，护灯纹只亮片刻便黯淡。",
        "稍熟后能一次画成闭合圆环，持续时长稳定在预期范围。",
        "熟练者可在灯罩弧面上均匀布纹，场域边界更少缺口。",
        "极熟练者画纹几乎不差毫厘，仍只提供同等的低阶防护。"
      ]
    },
    {
      "id": "spell_faith_08",
      "theory": "驱秽音以诵念和摇铃在空气中制造特定节律的魔力震荡，使低阶邪灵难以维持显形，从而被迫离开依附的人或物。震荡沿声波传播，被误认为邪灵的无辜者也会受到冲击，出现耳鸣、眩晕和短暂失神。仪式需要持续发声，中断则前功尽弃。",
      "casting": "左手摇铃，右手按在受术者肩头，以平稳音调诵念短句，同时将魔力随声送出，直到对方身体不再颤抖。",
      "failure": "诵念中途换气不当，铃声节奏散乱，魔力震荡会反冲施术者，使其喉头紧涩、耳鸣不止，而邪灵只是暂时退开，并未被驱离。",
      "counters": [
        "用厚毡堵住双耳并远离铃声范围，震荡便难以作用到身上。",
        "以更强的同频魔力抵消诵念节律，使驱秽音无法成形。"
      ],
      "socialConsequences": "乡间家庭遇到疑似附身时，常请会驱秽音的人上门，但施术后若发现被驱者是普通病人，家属会追究误伤责任。城镇医馆不反对这种仪式，却要求施术者先辨明症状，以免耽误真正需要医治的人。港口船员忌讳在船上摇铃，担心惊扰同行，因此多在码头空地举行。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学者诵念节奏不稳，铃声与魔力常对不上，效果时有时无。",
        "熟练后能维持均匀节律，震荡范围大致符合预期。",
        "更熟练者可分辨受术者反应，及时调整音调减少无辜者不适。",
        "极熟练者诵念几乎不散乱，仍无法区分邪灵与真正病人的本质。"
      ]
    },
    {
      "id": "spell_faith_09",
      "theory": "戒行护体将树脂涂抹在受术者手腕内侧，再以魔力沿树脂纹路编织一层与守戒誓言相系的防护。受术者只要在持续时间内不违背所立戒条，护体便维持；一旦破戒，树脂纹路会自行黯淡，防护随之消失。防护只削弱普通攻击带来的伤害，不阻挡魔法。",
      "casting": "取一粒树脂在掌心搓热，涂在受术者手腕内侧，同时口述一条简短戒条，将魔力随话语压入树脂纹路。",
      "failure": "树脂涂抹不均或戒条说得含糊，护体只覆盖半条手臂，破戒时也不会立刻消失，而是延迟片刻才失效，让受术者误以为防护仍在。",
      "counters": [
        "用烈酒擦去手腕上的树脂，护体纹路失去依附便当场消散。",
        "诱使受术者违背所立戒条，护体随破戒自行失效。"
      ],
      "socialConsequences": "立誓守戒的护卫和远行者愿意接受戒行护体，但雇主会要求戒条写进雇约，以便破戒时追责。酒馆老板不喜欢客人在店内立不饮酒的戒条，认为这会影响生意。若在他人身上施术而未说明破戒后果，事后常引发争执，甚至告到乡约或公会。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常涂不匀树脂，护体只覆盖部分身体。",
        "稍熟后能完整涂布手腕，防护时长接近预期。",
        "熟练者能清楚说明戒条，使受术者明白何时会失效。",
        "极熟练者护体纹路均匀稳定，仍只防普通攻击且不挡魔法。"
      ]
    }
  ]
}
